use std::fs::OpenOptions;
use std::io::Write;
use std::path::Path;

use cartograph_core::error::Result;
use cartograph_core::model::{DeadSymbolItem, ZombieFileReport};

/// Exports an AI Agent Context Exclusion Mask (.contextignore / .cursorignore)
pub fn export_ai_ignore_mask(
    output_path: &Path,
    zombie_files: &[ZombieFileReport],
    dead_symbols: &[DeadSymbolItem],
) -> Result<usize> {
    let mut file = OpenOptions::new()
        .create(true)
        .write(true)
        .truncate(true)
        .open(output_path)?;

    writeln!(
        file,
        "# Generated by Cartograph (.contextignore mask for AI agents)"
    )?;
    writeln!(
        file,
        "# Excludes dead code, zombie files, and abandoned components from AI agent context"
    )?;
    writeln!(
        file,
        "# Prevents token waste ($/mo) and deprecated pattern hallucinations.\n"
    )?;

    let mut count = 0;

    // 1. Zombie Files (100% dead)
    if !zombie_files.is_empty() {
        writeln!(file, "# --- 100% Dead Zombie Files ---")?;
        for zf in zombie_files {
            writeln!(file, "{}", zf.filepath)?;
            count += 1;
        }
        writeln!(file)?;
    }

    // 2. High-confidence dead components and functions
    writeln!(file, "# --- Dead Symbols and Abandoned Components ---")?;
    for item in dead_symbols {
        if item.confidence >= 0.90 {
            writeln!(
                file,
                "# {}:{} ({}: {})",
                item.filepath,
                item.start_line,
                item.category.as_str(),
                item.name
            )?;
            count += 1;
        }
    }

    file.flush()?;
    Ok(count)
}
